"""Cross-loop signals store (Loop Engineering follow-up, issue #179 E3).

The pipeline already produces artifacts (receipts), logs (events.jsonl) and
contracts (pipeline-state.json + mode files) — but its LEARNINGS evaporate at
sprint close: recurring failure classes hashed by the BEA5-F1 retry ledger,
DoD gate-failure hotspots, evidence-replay mismatches. Nothing machine-
readable feeds the next planning loop, so every sprint starts amnesiac.

This module is the missing compounding unit: a small append-only store at
`.synaptory/signals/signals.jsonl` that any loop can write and any loop can
read.

Writers: the sprint-retro ceremony runs `signals.py <project> harvest` to
distil the just-finished sprint's events/board into signals. Readers: the
sprint-planning ceremony (and PO refinement) run `signals.py <project> list`
and feed the output into planning.

A signal is one JSON object per line::

    {"ts": "...Z", "kind": "<kind>", "summary": "<one line>",
     "data": {...}, "source": "<producer>"}

Kinds harvested today:
  recurring_failure   — a (story, role) hit the same failure hash twice+
                        (the generator was not learning)
  dod_gate_hotspot    — a DoD check that failed on 2+ stories
  blocked_story       — a story left blocked (with its reason)
  replay_mismatch     — attested evidence that did not reproduce (#179 E1)

File-only and fail-safe: every write is best-effort append; a missing store
reads as no signals. Like all pipeline state, the store lives under
`.synaptory/` and never ships anywhere.
"""

from __future__ import annotations

import json
import os
import sys
import time
from collections import Counter
from pathlib import Path
from typing import Any

DEFAULT_LIST_LIMIT = 50

_README = """# Signals

Append-only, machine-readable learnings from past pipeline loops
(`signals.jsonl`, one JSON object per line — schema in
`hooks/lib/signals.py`). Written by the sprint-retro harvest; read by
sprint-planning and PO refinement so the next loop starts from what the last
one learned. Harvest is idempotent — each record carries a stable `key` and
a re-scan of the lifetime event log never re-appends a signal already
present. Do not hand-edit; stale lines age out by simply not being read
(readers take the most recent N).
"""


def _signals_dir(project_dir: str | os.PathLike) -> Path:
    return Path(project_dir) / ".synaptory" / "signals"


def _now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime()) + "Z"


def write_signal(
    project_dir: str | os.PathLike,
    kind: str,
    summary: str,
    data: dict[str, Any] | None = None,
    source: str | None = None,
    key: str | None = None,
) -> dict[str, Any] | None:
    """Append one signal; returns the record, or None when the write failed
    (best-effort — signal loss must never break the pipeline).

    `key` is a stable dedup identity (persisted on the record). When set and
    a signal with the same key already exists in the store, the write is a
    no-op and returns None — this is what makes `harvest_pipeline_signals`
    idempotent across repeated retros (a lifetime event log re-scanned every
    sprint must not keep re-appending the same failure)."""
    if key is not None and key in existing_keys(project_dir):
        return None
    record: dict[str, Any] = {"ts": _now(), "kind": kind, "summary": summary}
    if data:
        record["data"] = data
    if source:
        record["source"] = source
    if key is not None:
        record["key"] = key
    d = _signals_dir(project_dir)
    try:
        d.mkdir(parents=True, exist_ok=True)
        readme = d / "README.md"
        if not readme.exists():
            readme.write_text(_README, encoding="utf-8")
        with open(d / "signals.jsonl", "a", encoding="utf-8") as f:
            f.write(json.dumps(record, separators=(",", ":")) + "\n")
    except OSError:
        return None
    return record


def existing_keys(project_dir: str | os.PathLike) -> set[str]:
    """The set of stable dedup keys already in the store (missing store or
    unparseable lines contribute nothing)."""
    path = _signals_dir(project_dir) / "signals.jsonl"
    keys: set[str] = set()
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return keys
    for line in lines:
        try:
            rec = json.loads(line)
        except ValueError:
            continue
        if isinstance(rec, dict) and rec.get("key"):
            keys.add(rec["key"])
    return keys


def read_signals(
    project_dir: str | os.PathLike,
    kinds: list[str] | None = None,
    limit: int = DEFAULT_LIST_LIMIT,
) -> list[dict[str, Any]]:
    """Most-recent-first signals, optionally filtered by kind. Missing store
    or unparseable lines read as no signals."""
    path = _signals_dir(project_dir) / "signals.jsonl"
    out: list[dict[str, Any]] = []
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return out
    for line in reversed(lines):
        if len(out) >= max(0, limit):
            break
        try:
            rec = json.loads(line)
        except ValueError:
            continue
        if not isinstance(rec, dict):
            continue
        if kinds and rec.get("kind") not in kinds:
            continue
        out.append(rec)
    return out


def _read_events(project_dir: str | os.PathLike) -> list[dict[str, Any]]:
    path = (
        Path(project_dir) / ".synaptory" / ".orchestrator" / "events.jsonl"
    )
    events: list[dict[str, Any]] = []
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return events
    for line in lines:
        try:
            rec = json.loads(line)
        except ValueError:
            continue
        if isinstance(rec, dict):
            events.append(rec)
    return events


def harvest_pipeline_signals(
    project_dir: str | os.PathLike,
    state: dict[str, Any] | None = None,
    events: list[dict[str, Any]] | None = None,
    source: str = "sprint-retro",
) -> list[dict[str, Any]]:
    """Distil the current board + event log into signals and append them.

    Pure over its inputs when `state`/`events` are passed (tests); otherwise
    reads pipeline-state.json and events.jsonl. Returns the written records.
    """
    if state is None:
        try:
            from story_pipeline import _read_state

            state = _read_state(str(project_dir))
        except Exception:
            state = {}
    if events is None:
        events = _read_events(project_dir)

    written: list[dict[str, Any]] = []
    # Seed dedup from the store once, then track keys written this run — so a
    # lifetime event log re-scanned every retro yields each signal exactly
    # once (idempotency; the key EXCLUDES volatile fields like a growing
    # retry count so a persisting failure stays one signal, not a fresh one).
    seen = existing_keys(project_dir)

    def _emit(kind: str, summary: str, data: dict[str, Any], key: str) -> None:
        if key in seen:
            return
        rec = write_signal(project_dir, kind, summary, data, source, key=key)
        seen.add(key)
        if rec:
            written.append(rec)

    # 1. Recurring failure classes — the BEA5-F1 ledger already hashes
    #    failure reasons per (story, role); a hash seen twice+ means the
    #    generator repeated the exact same failure.
    for story in state.get("current_stories", []) or []:
        sid = str(story.get("id", ""))
        for role, hashes in (story.get("retry_failure_hashes") or {}).items():
            for reason_hash, n in Counter(hashes).items():
                if n >= 2:
                    _emit(
                        "recurring_failure",
                        f"{sid}/{role} repeated the same failure {n}x "
                        f"(hash {reason_hash})",
                        {"story_id": sid, "role": role,
                         "reason_hash": reason_hash, "count": n},
                        key=f"recurring_failure:{sid}:{role}:{reason_hash}",
                    )
        if story.get("state") == "blocked":
            reason = story.get("blocked_reason") or "no reason recorded"
            _emit(
                "blocked_story",
                f"{sid} left blocked: {reason}",
                {"story_id": sid,
                 "blocked_reason": story.get("blocked_reason")},
                key=f"blocked_story:{sid}:{reason}",
            )

    # 2. DoD gate hotspots — a check that failed on 2+ stories is a systemic
    #    gap (missing tooling, unclear contract), not a story-local slip.
    failed_by_check: dict[str, set[str]] = {}
    for ev in events:
        if ev.get("event") != "dod_evaluated":
            continue
        for check in ev.get("failed_required") or []:
            failed_by_check.setdefault(str(check), set()).add(
                str(ev.get("story_id", ""))
            )
    for check, sids in sorted(failed_by_check.items()):
        if len(sids) >= 2:
            _emit(
                "dod_gate_hotspot",
                f"DoD check '{check}' failed on {len(sids)} stories",
                {"check": check, "story_ids": sorted(sids)},
                key=f"dod_gate_hotspot:{check}",
            )

    # 3. Evidence-replay mismatches (#179 E1) — attested evidence that did
    #    not reproduce is the strongest possible signal about a receipt
    #    contract the agents are not honouring.
    for ev in events:
        if ev.get("event") != "evidence_replay_mismatch":
            continue
        _emit(
            "replay_mismatch",
            f"{ev.get('story_id')}: attested exit "
            f"{ev.get('attested_exit_code')} for `{ev.get('command')}` "
            f"did not reproduce (got {ev.get('replayed_exit_code')})",
            {k: ev.get(k) for k in (
                "story_id", "check", "role", "command",
                "attested_exit_code", "replayed_exit_code", "timed_out",
            )},
            key=f"replay_mismatch:{ev.get('story_id')}:{ev.get('check')}:"
                f"{ev.get('command')}",
        )

    return written


def main(argv: list[str]) -> int:
    if len(argv) < 3 or argv[2] not in ("harvest", "list"):
        print(
            "usage: signals.py <project_dir> harvest | list [kind ...]",
            file=sys.stderr,
        )
        return 2
    project_dir, cmd = argv[1], argv[2]
    if cmd == "harvest":
        written = harvest_pipeline_signals(project_dir)
        print(json.dumps({"written": len(written), "signals": written}, indent=2))
    else:
        kinds = argv[3:] or None
        print(json.dumps(read_signals(project_dir, kinds=kinds), indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
